'use client';

import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import { cn } from '@/lib/utils';

const linkVariants = cva('inline-flex items-center gap-1 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background rounded-sm', {
  variants: {
    variant: {
      default: 'text-primary hover:underline underline-offset-4',
      muted: 'text-muted-foreground hover:text-foreground',
      underline: 'underline underline-offset-4 hover:text-primary',
      arrow: 'font-medium text-primary hover:underline underline-offset-4',
      external: 'text-primary hover:underline underline-offset-4',
    },
  },
  defaultVariants: { variant: 'default' },
});

export type LinkProps = React.AnchorHTMLAttributes<HTMLAnchorElement> &
  VariantProps<typeof linkVariants> & {
    /** Render the child element (router Link) with link styling. */
    asChild?: boolean;
    /**
     * Force external handling (target=_blank + rel). Absolute http(s) hrefs
     * are detected automatically; mailto:/tel: links never open a new tab.
     */
    external?: boolean;
  };

const ABSOLUTE = /^https?:\/\//i;

/**
 * Inline link primitive with the project's link variants. Keeps a real
 * `<a href>` (SEO, modified clicks, middle-click) and adds safe external
 * handling: absolute URLs get target="_blank" + rel="noopener noreferrer"
 * and a screen-reader note, unless `external={false}`.
 *
 * For client-side routing, wrap your router's link: `<Link asChild><RouterLink …/></Link>`.
 */
export const Link = React.forwardRef<HTMLAnchorElement, LinkProps>(function Link(
  { className, variant, asChild = false, external, target, rel, children, ...props },
  ref
) {
  const isAbsolute = typeof props.href === 'string' && ABSOLUTE.test(props.href);
  const isExternal = external ?? isAbsolute;
  const Comp = asChild ? Slot : 'a';

  if (asChild) {
    return (
      <Comp
        ref={ref}
        className={cn(linkVariants({ variant }), className)}
        target={isExternal ? target ?? '_blank' : target}
        rel={isExternal ? rel ?? 'noopener noreferrer' : rel}
        {...props}
      >
        {children}
      </Comp>
    );
  }

  return (
    <Comp
      ref={ref}
      className={cn(linkVariants({ variant }), className)}
      target={isExternal ? target ?? '_blank' : target}
      rel={isExternal ? rel ?? 'noopener noreferrer' : rel}
      {...props}
    >
      {children}
      {isExternal && variant !== 'muted' && (
        <>
          <span aria-hidden="true" className="text-[0.75em]">
            ↗
          </span>
          <span className="sr-only">(opens in a new tab)</span>
        </>
      )}
    </Comp>
  );
});

export type LinkVariant = NonNullable<VariantProps<typeof linkVariants>['variant']>;

{
  "id": "link",
  "name": "Link",
  "tier": "atom",
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "link",
  "exportName": "Link",
  "description": "Inline link primitive with default/muted/underline/arrow/external variants, asChild router support and safe external handling.",
  "designIntent": "Every codebase re-implements inline links with inconsistent variants and unsafe target=_blank. Link centralizes the variants, keeps a real <a href> (SEO, modified clicks) and adds rel=noopener plus a screen-reader note for external URLs.",
  "props": [
    {
      "name": "href",
      "type": "string",
      "required": false,
      "description": "Destination URL (pass through or via asChild)."
    },
    {
      "name": "variant",
      "type": "'default' | 'muted' | 'underline' | 'arrow' | 'external'",
      "required": false,
      "defaultValue": "default",
      "description": "Visual style.",
      "enum": [
        "default",
        "muted",
        "underline",
        "arrow",
        "external"
      ]
    },
    {
      "name": "asChild",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Render the child (router Link) with link styling."
    },
    {
      "name": "external",
      "type": "boolean",
      "required": false,
      "description": "Force external handling; absolute http(s) URLs are auto-detected, mailto/tel never open a new tab."
    }
  ],
  "examples": [
    {
      "title": "Inline link",
      "code": "<Link href=\"/docs\">Read the docs</Link>\n<Link href=\"https://github.com\" variant=\"external\">GitHub</Link>",
      "description": "Internal links stay client-side; absolute URLs open safely in a new tab."
    },
    {
      "title": "Router link",
      "code": "<Link asChild variant=\"underline\"><RouterLink href=\"/posts\">Posts</RouterLink></Link>",
      "description": "Preserves prefetch and modified-click behavior."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Link for buttons",
      "explanation": "Actions belong in Button; Link is for navigation.",
      "example": "// Avoid\n<Link href=\"#\" onClick={save}>Save</Link>\n\n// Prefer\n<Button onClick={save}>Save</Button>"
    }
  ],
  "accessibility": [
    {
      "feature": "Real anchors",
      "implementation": "Renders <a href> so middle-click/modified clicks work",
      "userRequirements": "Pass descriptive link text, not 'click here'"
    },
    {
      "feature": "External notice",
      "implementation": "External links get rel=noopener noreferrer and a screen-reader note",
      "userRequirements": "Keep the sr-only note when overriding rows"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Link text",
      "guidelines": [
        "Describe the destination",
        "2-5 words"
      ],
      "goodExamples": [
        "Read the docs",
        "View on GitHub"
      ],
      "badExamples": [
        "Click here"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Card / List",
      "relationship": "asChild makes whole-card links safe",
      "example": "<Card asChild><Link href=\"/post\">…</Link></Card>"
    }
  ],
  "relatedComponents": [
    "Button",
    "Breadcrumb",
    "Card"
  ]
}
